<x-app-layout><x-slot name="header"><div><h1 class="text-xl font-bold text-slate-900">Sales Target Add</h1><p class="mt-1 text-sm text-slate-500">Set monthly target quantities and values by dealer and product.</p></div></x-slot><section x-data="salesTargetForm()" class="rounded-xl border border-slate-200 bg-white shadow-sm"><div class="bg-[#1fafa0] px-6 py-4 text-sm font-semibold text-white">SALES TARGET ADD</div><form method="POST" action="{{ route('sales-targets.store') }}" class="p-6">@csrf<div class="grid gap-6 md:grid-cols-2"><label class="text-sm font-semibold">Segment<select name="segment_id" class="mt-2 block w-full rounded-md border-slate-300 py-2.5 text-sm"><option value="">Select segment</option>@foreach($segments as $segment)<option value="{{ $segment->id }}">{{ $segment->name }}</option>@endforeach</select></label><label class="text-sm font-semibold">Remarks<textarea name="remarks" rows="2" class="mt-2 block w-full rounded-md border-slate-300 text-sm"></textarea></label><label class="text-sm font-semibold">Target month<select name="target_month" class="mt-2 block w-full rounded-md border-slate-300 py-2.5 text-sm">@foreach(range(1,12) as $month)<option value="{{ $month }}" @selected($month===now()->month)>{{ \Carbon\Carbon::create()->month($month)->format('F') }}</option>@endforeach</select></label><label class="text-sm font-semibold">Year<select name="target_year" class="mt-2 block w-full rounded-md border-slate-300 py-2.5 text-sm">@foreach(range(now()->year-1,now()->year+3) as $year)<option value="{{ $year }}">{{ $year }}</option>@endforeach</select></label></div><div class="mt-7 overflow-x-auto rounded-lg border border-sky-300"><table class="w-full min-w-[820px] text-sm"><thead class="bg-sky-500 text-white"><tr><th class="px-3 py-2 text-left">#</th><th class="px-3 py-2 text-left">Dealer</th><th class="px-3 py-2 text-left">Product</th><th class="px-3 py-2 text-left">Target Qty</th><th class="px-3 py-2 text-left">Price</th><th class="px-3 py-2 text-left">Target Value</th><th></th></tr></thead><tbody><template x-for="(item,index) in items" :key="index"><tr class="border-t"><td class="px-3" x-text="index+1"></td><td class="p-1"><select :name="`items[${index}][supplier_id]`" class="w-full rounded border-slate-300">@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}">{{ $supplier->name }}</option>@endforeach</select></td><td class="p-1"><select :name="`items[${index}][product_id]`" x-model="item.productId" @change="setPrice(item)" class="w-full rounded border-slate-300"><option value="">Select product</option>@foreach($products as $product)<option value="{{ $product->id }}" data-price="{{ $product->selling_price }}">{{ $product->name }}</option>@endforeach</select></td><td class="p-1"><input :name="`items[${index}][target_quantity]`" x-model.number="item.qty" type="number" min=".01" step=".01" class="w-full rounded border-slate-300"></td><td class="p-1"><input :name="`items[${index}][price]`" x-model.number="item.price" type="number" min="0" step=".01" class="w-full rounded border-slate-300"></td><td class="px-3 font-semibold" x-text="money(item.qty*item.price)"></td><td class="px-3"><button type="button" @click="remove(index)" x-show="items.length>1" class="text-rose-600">Remove</button></td></tr></template></tbody></table><button type="button" @click="items.push(blank())" class="m-3 rounded bg-sky-100 px-3 py-2 text-sm font-semibold text-sky-800">+ Add row</button></div><div class="mt-4 flex justify-end gap-10 text-sm font-bold"><span>Total Qty: <span x-text="totalQty"></span></span><span>Total Value: <span x-text="money(totalValue)"></span></span></div><div class="mt-6 flex gap-3"><button class="rounded-md bg-[#1f7d88] px-5 py-2.5 text-sm font-semibold text-white">Save</button><a href="{{ route('sales-targets.index') }}" class="crm-cancel-button rounded-md px-5 py-2.5 text-sm font-semibold">Cancel</a></div></form></section><script>function salesTargetForm(){return{items:[{productId:'',qty:1,price:0}],blank(){return{productId:'',qty:1,price:0}},remove(i){this.items.splice(i,1)},setPrice(item){let o=event.target.options[event.target.selectedIndex];item.price=Number(o.dataset.price||0)},get totalQty(){return this.items.reduce((a,x)=>a+(Number(x.qty)||0),0)},get totalValue(){return this.items.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.price)||0),0)},money(v){return Number(v||0).toLocaleString('en-BD',{minimumFractionDigits:2})}}}</script></x-app-layout>
